```sql
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create or replace function public.is_team_member(p_team_id bigint, p_role text)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = p_role
  );
$$;

create or replace function public.is_team_member(p_team_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
  );
$$;

create policy teams_select on public.teams
  for select
  to authenticated
  using (
    exists (
      select 1
      from public.team_members tm
      where tm.team_id = teams.id
        and tm.user_id = auth.uid()
    )
  );

create policy team_members_select on public.team_members
  for select
  to authenticated
  using (user_id = auth.uid());

create policy documents_select on public.documents
  for select
  to authenticated
  using (
    public.is_team_member(team_id)
    and deleted_at is null
  );

create policy documents_insert on public.documents
  for insert
  to authenticated
  with check (
    created_by = auth.uid()
    and public.is_team_member(team_id, 'editor')
  );

create policy documents_update on public.documents
  for update
  to authenticated
  using (
    public.is_team_member(team_id, 'editor')
    and deleted_at is null
  )
  with check (
    public.is_team_member(team_id, 'editor')
  );

create policy documents_delete on public.documents
  for delete
  to authenticated
  using (
    created_by = auth.uid()
    and deleted_at is null
    and public.is_team_member(team_id)
  );
```

