```sql
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

create or replace function public.is_suspended(p_user_id uuid)
returns boolean
language sql
security definer
stable
as $$
  select coalesce(
    (select suspended from public.accounts where user_id = p_user_id),
    false
  );
$$;

create or replace function public.is_file_owner(p_file_id bigint)
returns uuid
language sql
security definer
stable
as $$
  select f.owner_id from public.files f where f.id = p_file_id;
$$;

create or replace function public.can_read_shared_file(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from public.file_shares fs
    where fs.file_id = p_file_id
      and fs.shared_with = p_user_id
      and fs.expires_at is null
      or fs.expires_at > now()
  );
$$;

create or replace function public.can_edit_shared_file(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from public.file_shares fs
    where fs.file_id = p_file_id
      and fs.shared_with = p_user_id
      and fs.can_edit
      and (fs.expires_at is null or fs.expires_at > now())
  );
$$;

create policy accounts_select on public.accounts
  for select
  to authenticated
  using (user_id = auth.uid());

create policy files_select on public.files
  for select
  to authenticated
  using (
    public.is_suspended(auth.uid()) = false
    and (
      owner_id = auth.uid()
      or public.can_read_shared_file(id, auth.uid())
    )
  );

create policy files_insert on public.files
  for insert
  to authenticated
  with check (
    public.is_suspended(auth.uid()) = false
    and owner_id = auth.uid()
  );

create policy files_update on public.files
  for update
  to authenticated
  using (
    public.is_suspended(auth.uid()) = false
    and owner_id = auth.uid()
  )
  with check (
    public.is_suspended(auth.uid()) = false
    and owner_id = auth.uid()
  );

create policy files_delete on public.files
  for delete
  to authenticated
  using (
    public.is_suspended(auth.uid()) = false
    and owner_id = auth.uid()
  );

create policy file_shares_select on public.file_shares
  for select
  to authenticated
  using (
    public.is_suspended(auth.uid()) = false
    and (
      public.is_file_owner(file_id) = auth.uid()
      or shared_with = auth.uid()
    )
  );

create policy file_shares_insert on public.file_shares
  for insert
  to authenticated
  with check (
    public.is_suspended(auth.uid()) = false
    and public.is_file_owner(file_id) = auth.uid()
  );

create policy file_shares_update on public.file_shares
  for update
  to authenticated
  using (
    public.is_suspended(auth.uid()) = false
    and public.is_file_owner(file_id) = auth.uid()
  )
  with check (
    public.is_suspended(auth.uid()) = false
    and public.is_file_owner(file_id) = auth.uid()
  );

create policy file_shares_delete on public.file_shares
  for delete
  to authenticated
  using (
    public.is_suspended(auth.uid()) = false
    and public.is_file_owner(file_id) = auth.uid()
  );
```

