create or replace function public.invoice_is_draft(p_invoice_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select coalesce(
    (select i.status = 'draft' from public.invoices i where i.id = p_invoice_id),
    false
  );
$$;

create or replace function public.invoice_status_transition_allowed(p_old_status text, p_new_status text)
returns boolean
language sql
security definer
stable
as $$
  case
    when p_old_status is null or p_new_status is null then false
    when p_old_status = 'draft' and p_new_status in ('draft', 'sent') then true
    when p_old_status = 'sent' and p_new_status in ('paid', 'void') then true
    else false
  end;
$$;

