  for insert
  to authenticated
  with check (
    created_by = auth.uid()
    and status = 'draft'
  );

create policy invoices_update on public.invoices
  for update
  to authenticated
  using (
    (
      created_by = auth.uid()
      and public.invoice_is_draft(id)
    )
    or
    public.is_finance_staff(auth.uid())
    and status = 'sent'
  )
  with check (
    (
      created_by = auth.uid()
      and (
        (status = 'draft')
        or (
          status = 'sent'
          and public.invoice_is_draft(id) is false
        )
      )
    )
    or
    public.is_finance_staff(auth.uid())
    and status in ('paid', 'void')
  );

create policy invoices_delete on public.invoices
  for delete
  to authenticated
  using (
    created_by = auth.uid()
    and public.invoice_is_draft(id)
  );
