    where user_id = p_user_id
  );
$$;

create or replace function public.invoice_status_change_allowed(p_invoice_id bigint, p_new_status text)
returns boolean
language sql
security definer
as $$
  select case
    when p_new_status not in ('draft', 'sent', 'paid', 'void') then false
    when exists (
      select 1
      from public.invoices i
      where i.id = p_invoice_id
      and i.created_by = auth.uid()
      and i.status = 'draft'
    ) then true
    when public.is_finance_staff(auth.uid())
         and exists (
           select 1
           from public.invoices i
           where i.id = p_invoice_id
           and i.status = 'sent'
           and p_new_status in ('paid', 'void')
         ) then true
    else false
  end;
$$;

create or replace function public.invoice_customer_amount_edit_allowed(p_invoice_id bigint)
returns boolean
language sql
security definer
as $$
  select exists (
    select 1
    from public.invoices i
    where i.id = p_invoice_id
    and i.created_by = auth.uid()
    and i.status = 'draft'
  );
$$;

create or replace function public.invoice_created_by_immutable(p_invoice_id bigint)
returns boolean
language sql
security definer
as $$
  select true;
$$;

create or replace function public.before_invoice_update()
returns trigger
language plpgsql
security definer
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'created_by cannot be changed';
  end if;

  if old.status != 'draft' then
    if new.customer is distinct from old.customer then
      raise exception 'customer can only be changed on draft invoices';
    end if;
    if new.amount is distinct from old.amount then
      raise exception 'amount can only be changed on draft invoices';
    end if;
  end if;

  if old.status = 'draft' then
    if new.status not in ('draft', 'sent') then
      raise exception 'draft invoices can only be changed to draft or sent';
    end if;
    if new.customer is distinct from old.customer
       or new.amount is distinct from old.amount then
      if not public.invoice_customer_amount_edit_allowed(old.id) then
        raise exception 'only the creator can change customer and amount on draft invoices';
      end if;
    end if;
  elsif old.status = 'sent' then
    if new.status not in ('paid', 'void') then
      raise exception 'sent invoices can only be changed to paid or void by finance staff';
    end if;
    if new.customer is distinct from old.customer
       or new.amount is distinct from old.amount
       or new.created_by is distinct from old.created_by then
      raise exception 'only status can be changed on sent invoices';
    end if;
  end if;

  return new;
end;
$$;

create trigger before_invoice_update_trigger
before update on public.invoices
for each row
execute function public.before_invoice_update();

