for select
to authenticated
using (
  created_by = auth.uid()
  or public.is_finance_staff(auth.uid())
);

create policy invoices_insert on public.invoices
for insert
to authenticated
with check (
  created_by = auth.uid()
  and status = 'draft'
);

create policy invoices_update on public.invoices
for update
to authenticated
using (
  public.is_finance_staff(auth.uid())
  or (
    created_by = auth.uid()
    and (
      (status = 'draft' and new.status in ('draft', 'sent'))
      or (status = 'sent' and new.status in ('paid', 'void'))
    )
  )
)
with check (
  public.is_finance_staff(auth.uid())
  or (
    created_by = auth.uid()
    and (
      (status = 'draft' and new.status in ('draft', 'sent'))
      or (status = 'sent' and new.status in ('paid', 'void'))
    )
  )
);

create policy invoices_delete on public.invoices
for delete
to authenticated
using (
  created_by = auth.uid()
  and status = 'draft'
);
