create or replace function public.invoices_before_update()
returns trigger
language plpgsql
security definer
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.created_by != old.created_by then
    raise exception 'created_by cannot be changed';
  end if;

  if old.created_by is distinct from auth.uid() then
    if not public.is_finance_staff(auth.uid()) then
      raise exception 'only the creator or finance staff can update this invoice';
    end if;
  end if;

  if old.status != 'draft' and old.status != 'sent' then
    raise exception 'invoice status is not draft or sent';
  end if;

  if public.is_finance_staff(auth.uid()) then
    if old.status = 'sent' and new.status in ('paid', 'void') then
      if new.customer is distinct from old.customer or new.amount is distinct from old.amount then
        raise exception 'finance staff can only change status on sent invoices';
      end if;
      return new;
    end if;
  end if;

  if old.created_by = auth.uid() and old.status = 'draft' then
    if new.status in ('draft', 'sent') then
      if new.customer is distinct from old.customer or new.amount is distinct from old.amount then
        if not public.invoice_customer_amount_change_allowed(old.id, new.customer, new.amount) then
          raise exception 'only creator can change customer or amount';
        end if;
      end if;
      return new;
    end if;
  end if;

  raise exception 'invalid invoice update';
end;
$$;

create trigger invoices_before_update_trigger
  before update on public.invoices
  for each row
  execute function public.invoices_before_update();
