alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.invites enable row level security;

create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

create or replace function public.accept_invite(p_token text)
returns bigint
language plpgsql
security definer
as $$
declare
  v_org_id bigint;
  v_email text;
begin
  if auth.uid() is null then
    raise exception 'User must be signed in';
  end if;

  select i.org_id, i.email
  into v_org_id, v_email
  from public.invites i
  where i.token = p_token
  for update;

  if not found then
    raise exception 'Invalid invite token';
  end if;

  if v_email is null then
    raise exception 'Invite does not exist';
  end if;

  if v_email <> lower(auth.jwt() ->> 'email') then
    raise exception 'Invite email does not match user verified email';
  end if;

  if v_email is null then
    raise exception 'Invite email is missing';
  end if;

  if v_email is distinct from lower(auth.jwt() ->> 'email') then
    raise exception 'Invite email does not match user verified email';
  end if;

  if v_org_id is null then
    raise exception 'Invalid organization';
  end if;

  if i.expires_at < now() then
    raise exception 'Invite has expired';
  end if;

  if i.accepted_at is not null then
    raise exception 'Invite has already been accepted';
  end if;

  update public.invites
  set accepted_at = now()
  where token = p_token;

  insert into public.org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), i.role);

  return v_org_id;
end;
$$;

create policy orgs_select on public.orgs
  for select
  to authenticated
  using (public.is_org_member(id));

create policy org_members_select on public.org_members
  for select
  to authenticated
  using (public.is_org_member(org_id));

create policy invites_select on public.invites
  for select
  to authenticated
  using (public.is_org_admin(org_id));

create policy invites_insert on public.invites
  for insert
  to authenticated
  with check (public.is_org_admin(org_id) and invited_by = auth.uid() and accepted_at is null and expires_at > now());

create policy invites_delete on public.invites
  for delete
  to authenticated
  using (public.is_org_admin(org_id));
```

