  for delete
  to authenticated
  using (public.is_org_admin(org_id));

create function public.accept_invite(p_token text) returns bigint
language plpgsql
security definer
as $$
declare
  v_org_id bigint;
  v_email text;
begin
  if auth.uid() is null then
    raise exception 'User must be signed in';
  end if;

  select i.org_id, i.email
  into v_org_id, v_email
  from public.invites i
  where i.token = p_token
  for update;

  if not found then
    raise exception 'Invalid invite token';
  end if;

  if i.accepted_at is not null then
    raise exception 'Invite has already been accepted';
  end if;

  if i.expires_at <= now() then
    raise exception 'Invite has expired';
  end if;

  v_email := lower(v_email);

  if lower(auth.jwt() ->> 'email') is null then
    raise exception 'User email not found in JWT';
  end if;

  if lower(auth.jwt() ->> 'email') != v_email then
    raise exception 'Invite email does not match user verified email';
  end if;

  perform public.org_members_insert(
    p_org_id => v_org_id,
    p_user_id => auth.uid(),
    p_role => i.role
  );

  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_org_id;
end;
$$;

create function public.org_members_insert(p_org_id bigint, p_user_id uuid, p_role text) returns void
language plpgsql
security definer
as $$
begin
  insert into public.org_members (org_id, user_id, role)
  values (p_org_id, p_user_id, p_role);
end;
