create or replace function public.enforce_segment_update()
returns trigger
language plpgsql
security definer
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.source_text is distinct from old.source_text then
    raise exception 'source_text cannot be changed';
  end if;

  if old.status != 'draft' then
    raise exception 'segment is not in draft status';
  end if;

  if new.translated_by is distinct from auth.uid() then
    raise exception 'translated_by must be the current user';
  end if;

  if public.is_project_translator(old.project_id, old.lang) then
    new.status := 'draft';
    return new;
  end if;

  if public.is_project_reviewer(old.project_id, old.lang) then
    new.status := new.status;
    return new;
  end if;

  raise exception 'user does not have permission to update this segment';
end;
$$;

