create or replace function public.enforce_segment_update()
returns trigger
language plpgsql
security definer
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.source_text is distinct from old.source_text then
    raise exception 'source_text cannot be changed';
  end if;

  if old.status = 'reviewed' then
    raise exception 'reviewed segments cannot be changed';
  end if;

  if new.translated_by is distinct from auth.uid() then
    raise exception 'translated_by must be the performing user';
  end if;

  if tg_op = 'UPDATE' then
    if new.status = 'reviewed' then
      if not public.is_project_reviewer(old.project_id, old.lang) then
        raise exception 'only reviewers can mark segments as reviewed';
      end if;
    else
      if not public.is_project_translator(old.project_id, old.lang) then
        raise exception 'only translators can update draft segments';
      end if;
    end if;
  else
    if not public.is_project_translator(new.project_id, new.lang) then
      raise exception 'only translators can create segments';
    end if;
    if new.status != 'draft' then
      raise exception 'new segments must be in draft status';
    end if;
  end if;

  return new;
end;
$$;

