create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_envelope_status text;
  v_caller_id uuid := auth.uid();
  v_sign_order integer;
  v_signed_count integer;
  v_total_count integer;
begin
  if v_caller_id is null then
    raise exception 'Not authenticated';
  end if;

  select e.status into v_envelope_status
  from public.envelopes e
  where e.id = p_envelope_id;

  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_envelope_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  select r.sign_order into v_sign_order
  from public.envelope_recipients r
  where r.envelope_id = p_envelope_id
    and r.user_id = v_caller_id;

  if not found then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  if r.signed_at is not null then
    raise exception 'Caller has already signed this envelope';
  end if;

  update public.envelope_recipients r
  set signed_at = now()
  where r.envelope_id = p_envelope_id
    and r.user_id = v_caller_id;

  select count(*) into v_signed_count
  from public.envelope_recipients r
  where r.envelope_id = p_envelope_id
    and r.signed_at is not null;

  select count(*) into v_total_count
  from public.envelope_recipients r
  where r.envelope_id = p_envelope_id;

  if v_signed_count < v_total_count then
    return v_envelope_status;
  end if;

  update public.envelopes e
  set status = 'completed'
  where e.id = p_envelope_id;

  return 'completed';
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_envelope_status text;
  v_sender_id uuid;
begin
  select e.status, e.sender_id into v_envelope_status, v_sender_id
  from public.envelopes e
  where e.id = p_envelope_id;

  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_sender_id != auth.uid() then
    raise exception 'Only the sender can void an envelope';
  end if;

  if v_envelope_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  update public.envelopes e
  set status = 'voided'
  where e.id = p_envelope_id;

  return 'voided';
end;
$$;
