create or replace function public.enforce_permit_insert_constraints()
returns trigger
language plpgsql
security definer
as $$
begin
  if public.count_active_permits(new.unit_id) >= 2 then
    raise exception 'Unit already has 2 or more active permits';
  end if;

  if new.revoked is distinct from false then
    raise exception 'New permits cannot be revoked';
  end if;

  if new.valid_until < current_date then
    raise exception 'Permit valid_until must be today or later';
  end if;

  if new.valid_until > current_date + interval '365 days' then
    raise exception 'Permit valid_until must be within 365 days from today';
  end if;

  return new;
end;
$$;

