before insert on public.permits
for each row
execute function public.enforce_permit_insert_constraints();

create or replace function public.enforce_permit_update_constraints()
returns trigger
language plpgsql
security definer
as $$
begin
  if old.revoked is true then
    raise exception 'Cannot un-revoke a permit';
  end if;

  if tg_op = 'INSERT' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.plate is distinct from old.plate
     or new.valid_until is distinct from old.valid_until
     or new.revoked is distinct from old.revoked then
    raise exception 'Only plate can be updated';
  end if;

  return new;
end;
$$;

